  "fixed_code": "import base64\nimport json\nfrom typing import Dict\nfrom flask import Flask, jsonify, request\n\napp = Flask(__name__)\n\nDEFAULT_PREFS = {\"theme\": \"light\"}\n\ndef load_preferences() -> Dict[str, str]:\n    \"\"\"Loads user preferences from a base64-encoded JSON cookie. Returns a default theme if no cookie is present.\"\"\"\n    cookie = request.cookies.get(\"prefs\")\n    if not cookie:\n        return DEFAULT_PREFS.copy()\n    try:\n        data = json.loads(base64.b64decode(cookie))\n        if isinstance(data, dict) and \"theme\" in data:\n            return data\n    except (json.JSONDecodeError, ValueError, TypeError):\n        pass\n    return DEFAULT_PREFS.copy()\n\n@app.route(\"/settings\")\ndef settings():\n    prefs = load_preferences()\n    return jsonify(theme=prefs.get(\"theme\", DEFAULT_PREFS[\"theme\"]))\n"
